{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * SPDX-License-Identifier: BSD-3-Clause
 */

// Interpolate Nearest — AscendC kernel (device side)
// Input:  x[N, C, H, W]
// Output: y[N, C, outH, outW]
// Algorithm: nearest-neighbor interpolation
//
// Block tiling: N*C pairs distributed across cores
// Each core processes output rows for assigned N*C pairs
// For each output row:
//   - Load source row x[n, c, h_in, :] into UB
//   - For each column tile, compute w_in indices and gather
//   - Write output tile to GM

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b) {
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T>& dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T>& src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline void CastInputToFp32(
    AscendC::LocalTensor<float>& dst,
    AscendC::LocalTensor<T>& src,
    AscendC::TBuf<AscendC::TPosition::VECCALC>& castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void CastOutputFromFp32(
    AscendC::LocalTensor<T>& dst,
    AscendC::LocalTensor<float>& src,
    AscendC::TBuf<AscendC::TPosition::VECCALC>& castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<T>();
    } else {
        dst = castBuf.Get<T>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Kernel class
// =========================================================================

template <typename T>
class KernelInterpolateNearest {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t N, int32_t C, int32_t H, int32_t W,
        int32_t outH, int32_t outW,
        int32_t alignCorners,
        int32_t ncBlock, int32_t ncNum, int32_t usedCoreNum, int32_t tasksPerCore,
        int32_t tileW, int32_t wTileCount)
    {
        this->N = N; this->C = C; this->H = H; this->W = W;
        this->outH = outH; this->outW = outW;
        this->alignCorners = alignCorners;
        this->ncBlock = ncBlock; this->ncNum = ncNum;
        this->usedCoreNum = usedCoreNum; this->tasksPerCore = tasksPerCore;
        this->tileW = tileW; this->wTileCount = wTileCount;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x),
            static_cast<uint64_t>(N) * C * H * W);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y),
            static_cast<uint64_t>(N) * C * outH * outW);

        if ASCEND_IS_AIV {
            InitAivBuffers();
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= ncNum) { continue; }

                for (int ncOff = 0; ncOff < ncBlock; ++ncOff) {
                    int ncIdx = bx * ncBlock + ncOff;
                    if (ncIdx >= N * C) { continue; }

                    int nIdx = ncIdx / C;
                    int cIdx = ncIdx % C;

                    // Process each output row
                    for (int hOut = 0; hOut < outH; ++hOut) {
                        ProcessOutputRow(nIdx, cIdx, hOut);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessOutputRow(int nIdx, int cIdx, int hOut) {
        // Compute source row index
        int hIn = ComputeNearestIdx(hOut, H, outH, alignCorners);

        // Load source row into UB
        CopyInX(nIdx, cIdx, hIn);

        // Process output columns in tiles
        for (int wTileIdx = 0; wTileIdx < wTileCount; ++wTileIdx) {
            int wStart = wTileIdx * tileW;
            int curW = (wStart + tileW <= outW) ? tileW : (outW - wStart);
            if (curW <= 0) { continue; }

            ComputeTile(curW, wStart);
            CopyOutY(nIdx, cIdx, hOut, wStart, curW);
        }
    }

    __aicore__ inline void CopyInX(int nIdx, int cIdx, int hIn) {
        xInLocal_ = xInQueue_.AllocTensor<T>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(nIdx) * C * H * W
            + static_cast<uint64_t>(cIdx) * H * W
            + static_cast<uint64_t>(hIn) * W], static_cast<uint32_t>(W));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int nIdx, int cIdx, int hOut, int wStart, int curW) {
        yOutLocal_ = yOutQueue_.DeQue<T>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(nIdx) * C * outH * outW
            + static_cast<uint64_t>(cIdx) * outH * outW
            + static_cast<uint64_t>(hOut) * outW
            + static_cast<uint32_t>(wStart)], yOutLocal_, static_cast<uint32_t>(curW));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeTile(int curW, int wStart) {
        // DeQue input row
        AscendC::LocalTensor<T> xInDeq = xInQueue_.DeQue<T>();

        // Cast input to FP32
        AscendC::LocalTensor<float> xFp32;
        CastInputToFp32(xFp32, xInDeq, xCastBuf_, W);

        // Allocate output tile
        yOutLocal_ = yOutQueue_.AllocTensor<T>();

        // Compute element-by-element using scalar index computation
        // (unavoidable for nearest-neighbor mapping)
        for (int wOff = 0; wOff < curW; ++wOff) {
            int wOut = wStart + wOff;
            int wIn = ComputeNearestIdx(wOut, W, outW, alignCorners);

            // Read from UB row at position wIn
            float val = xFp32.GetValue(wIn);

            // Prepare output for FP32 write
            if constexpr (std::is_same_v<T, float>) {
                yFp32Local_ = yOutLocal_.template ReinterpretCast<float>();
            } else {
                yFp32Local_ = yCastBuf_.Get<float>();
            }
            yFp32Local_.SetValue(wOff, val);
        }

        // Cast output back if needed
        if constexpr (!std::is_same_v<T, float>) {
            AscendC::Cast(yOutLocal_, yFp32Local_, AscendC::RoundMode::CAST_NONE, curW);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // EnQue output
        yOutQueue_.EnQue(yOutLocal_);

        // Free input
        xInQueue_.FreeTensor(xInDeq);
    }

    __aicore__ inline int32_t ComputeNearestIdx(
        int32_t idxOut, int32_t inSize, int32_t outSize, int32_t alignCorners)
    {
        float coord;
        if (alignCorners) {
            // coord = idxOut * (inSize - 1) / max(outSize - 1, 1)
            float scaleNum = static_cast<float>(inSize - 1);
            int32_t denom = (outSize > 1) ? (outSize - 1) : 1;
            float scaleDen = static_cast<float>(denom);
            coord = static_cast<float>(idxOut) * scaleNum / scaleDen;
            // round: floor(coord + 0.5f)
            coord = coord + 0.5f;
        } else {
            // coord = idxOut * inSize / outSize (floor)
            coord = static_cast<float>(idxOut) *
                static_cast<float>(inSize) / static_cast<float>(outSize);
        }

        int32_t result = static_cast<int32_t>(coord);
        // Clamp to [0, inSize - 1]
        if (result < 0) { result = 0; }
        if (result >= inSize) { result = inSize - 1; }
        return result;
    }

    __aicore__ inline void InitAivBuffers() {
        // One input row (size W) and one output tile (size tileW)
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, tileW * sizeof(T));
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, tileW * sizeof(T));

        if constexpr (!std::is_same_v<T, float>) {
            // Cast buffer for input row (fp32)
            pipe_.InitBuffer(xCastBuf_, tileW * sizeof(float));
            // Cast buffer for output tile (fp32)
            pipe_.InitBuffer(yCastBuf_, tileW * sizeof(float));
        }
    }

private:
    // Problem dimensions
    int32_t N, C, H, W;
    int32_t outH, outW;
    int32_t alignCorners;

    // Tiling
    int32_t ncBlock, ncNum, usedCoreNum, tasksPerCore;
    int32_t tileW, wTileCount;

    // GM tensors
    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;

    // Pipe
    AscendC::TPipe pipe_;

    // Queues
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // Cast buffers (only for fp16/bf16)
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    // Locals
    AscendC::LocalTensor<T> xInLocal_;
    AscendC::LocalTensor<T> yOutLocal_;
    AscendC::LocalTensor<float> yFp32Local_;
};

