// Interpolate Nearest — op_host: tiling + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_interpolate_nearest.h"

namespace ascend_kernel {

at::Tensor interpolate_nearest(
    const at::Tensor& x,
    at::IntArrayRef size,
    at::optional<at::IntArrayRef> scale_factor,
    c10::string_view mode,
    at::optional<bool> align_corners,
    at::optional<bool> recompute_scale_factor,
    bool antialias)
{
    // Input validation
    TORCH_CHECK(x.dim() == 4, "x must be 4D [N, C, H, W]");
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
        x.scalar_type() == at::kHalf ||
        x.scalar_type() == at::kBFloat16,
        "x must be float32, float16, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int32_t N = static_cast<int32_t>(x.sizes()[0]);
    int32_t C = static_cast<int32_t>(x.sizes()[1]);
    int32_t H = static_cast<int32_t>(x.sizes()[2]);
    int32_t W = static_cast<int32_t>(x.sizes()[3]);

    // Determine output size
    int32_t outH, outW;
    if (size.size() == 2) {
        outH = static_cast<int32_t>(size[0]);
        outW = static_cast<int32_t>(size[1]);
    } else if (scale_factor.has_value() && scale_factor.value().size() == 2) {
        outH = static_cast<int32_t>(H * scale_factor.value()[0]);
        outW = static_cast<int32_t>(W * scale_factor.value()[1]);
    } else if (scale_factor.has_value() && scale_factor.value().size() == 1) {
        outH = static_cast<int32_t>(H * scale_factor.value()[0]);
        outW = static_cast<int32_t>(W * scale_factor.value()[0]);
    } else {
        outH = H;
        outW = W;
    }

    at::Tensor y = at::empty({N, C, outH, outW}, x.options());

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // align_corners flag
    int32_t alignCornersFlag = 0;
    if (align_corners.has_value() && align_corners.value()) {
        alignCornersFlag = 1;
    }

    // Tiling: N*C pairs across cores
    int32_t ncTotal = N * C;
    int32_t ncBlock = 32;
    if (ncTotal < 32) { ncBlock = 16; }
    if (ncTotal < 16) { ncBlock = 8; }
    if (ncTotal < 8)  { ncBlock = 4; }
    if (ncTotal < 4)  { ncBlock = 2; }
    if (ncTotal < 2)  { ncBlock = 1; }

    int32_t ncNum = (ncTotal + ncBlock - 1) / ncBlock;
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
    int32_t usedCoreNum = std::min(coreNum, ncNum);
    if (usedCoreNum < 1) { usedCoreNum = 1; }
    int32_t tasksPerCore = (ncNum + usedCoreNum - 1) / usedCoreNum;

    // Column tile size
    int32_t tileW = 128;

    // Number of column tiles
    int32_t wTileCount = (outW + tileW - 1) / tileW;

    // All params must be left values for EXEC_KERNEL_CMD
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(interpolate_nearest, blockDim,
        x, y,
        N, C, H, W, outH, outW,
        alignCornersFlag,
        ncBlock, ncNum, usedCoreNum, tasksPerCore,
        tileW, wTileCount,
        dtypeFlag);

    return y;
}

}  // namespace ascend_kernel
