6	// Interpolate Nearest — AscendC kernel (device side)
7	// Input:  x[N, C, H, W]
8	// Output: y[N, C, outH, outW]
9	// Algorithm: nearest-neighbor interpolation
10	//
11	// Block tiling: N*C pairs distributed across cores
12	// Each core processes output rows for assigned N*C pairs
13	// For each output row:
14	//   - Load source row x[n, c, h_in, :] into UB
15	//   - For each column tile, compute w_in indices and gather
16	//   - Write output tile to GM
17	
18	#include "kernel_operator.h"
19	
20	constexpr int32_t BUFFER_NUM = 2;
21	
22	// ---------------------------------------------------------------------------
23	// Helpers
24	// ---------------------------------------------------------------------------
25	
26	__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b) {
27	    if (b == 0) { return 0; }
28	    return (a + b - 1) / b;
29	}
30	
31	template <typename T>
32	__aicore__ inline void LoadGmToUb(
33	    AscendC::LocalTensor<T>& dst,
34	    AscendC::GlobalTensor<T> src,
35	    uint32_t count)
36	{
37	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
38	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
39	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
40	}
41	
42	template <typename T>
43	__aicore__ inline void StoreUbToGm(
44	    AscendC::GlobalTensor<T> dst,
45	    AscendC::LocalTensor<T>& src,
46	    uint32_t count)
47	{
48	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
49	    AscendC::DataCopyPad(dst, src, copyParams);
50	}
51	
52	template <typename T>
53	__aicore__ inline void CastInputToFp32(
54	    AscendC::LocalTensor<float>& dst,
55	    AscendC::LocalTensor<T>& src,
56	    AscendC::TBuf<AscendC::TPosition::VECCALC>& castBuf,
57	    int32_t count)
58	{
59	    if constexpr (std::is_same_v<T, float>) {
60	        dst = src.template ReinterpretCast<float>();
61	    } else {
62	        dst = castBuf.Get<float>();
63	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
64	        AscendC::PipeBarrier<PIPE_V>();
65	    }
66	}
67	
68	template <typename T>
69	__aicore__ inline void CastOutputFromFp32(
70	    AscendC::LocalTensor<T>& dst,
71	    AscendC::LocalTensor<float>& src,
72	    AscendC::TBuf<AscendC::TPosition::VECCALC>& castBuf,
73	    int32_t count)
74	{
75	    if constexpr (std::is_same_v<T, float>) {
76	        dst = src.template ReinterpretCast<T>();
77	    } else {
78	        dst = castBuf.Get<T>();
79	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
80	        AscendC::PipeBarrier<PIPE_V>();
81	    }
82	}
83	
84	// =========================================================================
85	// Kernel class
86	// =========================================================================
87	
88	template <typename T>
89	class KernelInterpolateNearest {
90	public:
91	    __aicore__ inline void Init(
92	        GM_ADDR x, GM_ADDR y,
93	        int32_t N, int32_t C, int32_t H, int32_t W,
94	        int32_t outH, int32_t outW,
95	        int32_t alignCorners,
96	        int32_t ncBlock, int32_t ncNum, int32_t usedCoreNum, int32_t tasksPerCore,
97	        int32_t tileW, int32_t wTileCount)
98	    {
99	        this->N = N; this->C = C; this->H = H; this->W = W;
100	        this->outH = outH; this->outW = outW;
101	        this->alignCorners = alignCorners;
102	        this->ncBlock = ncBlock; this->ncNum = ncNum;
103	        this->usedCoreNum = usedCoreNum; this->tasksPerCore = tasksPerCore;
104	        this->tileW = tileW; this->wTileCount = wTileCount;
105	
106	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x),
107	            static_cast<uint64_t>(N) * C * H * W);
108	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y),
109	            static_cast<uint64_t>(N) * C * outH * outW);
110	
111	        if ASCEND_IS_AIV {
112	            InitAivBuffers();
113	        }
114	    }
115	
116	    __aicore__ inline void Process() {
117	        if ASCEND_IS_AIV {
118	            int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
119	
120	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
121	                int bx = coreIdx * tasksPerCore + localIdx;
122	                if (bx >= ncNum) { continue; }
123	
124	                for (int ncOff = 0; ncOff < ncBlock; ++ncOff) {
125	                    int ncIdx = bx * ncBlock + ncOff;
126	                    if (ncIdx >= N * C) { continue; }
127	
128	                    int nIdx = ncIdx / C;
129	                    int cIdx = ncIdx % C;
130	
131	                    // Process each output row
132	                    for (int hOut = 0; hOut < outH; ++hOut) {
133	                        ProcessOutputRow(nIdx, cIdx, hOut);
134	                    }
135	                }
136	            }
137	        }
138	    }
139	
140	private:
141	    __aicore__ inline void ProcessOutputRow(int nIdx, int cIdx, int hOut) {
142	        // Compute source row index
143	        int hIn = ComputeNearestIdx(hOut, H, outH, alignCorners);
144	
145	        // Load source row into UB
146	        CopyInX(nIdx, cIdx, hIn);
147	
148	        // Process output columns in tiles
149	        for (int wTileIdx = 0; wTileIdx < wTileCount; ++wTileIdx) {
150	            int wStart = wTileIdx * tileW;
151	            int curW = (wStart + tileW <= outW) ? tileW : (outW - wStart);
152	            if (curW <= 0) { continue; }
153	
154	            ComputeTile(curW, wStart);
155	            CopyOutY(nIdx, cIdx, hOut, wStart, curW);
156	        }
157	    }
158	
159	    __aicore__ inline void CopyInX(int nIdx, int cIdx, int hIn) {
160	        xInLocal_ = xInQueue_.AllocTensor<T>();
161	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(nIdx) * C * H * W
162	            + static_cast<uint64_t>(cIdx) * H * W
163	            + static_cast<uint64_t>(hIn) * W], static_cast<uint32_t>(W));
164	        xInQueue_.EnQue(xInLocal_);
165	    }
166	
167	    __aicore__ inline void CopyOutY(int nIdx, int cIdx, int hOut, int wStart, int curW) {
168	        yOutLocal_ = yOutQueue_.DeQue<T>();
169	        StoreUbToGm(yGM_[static_cast<uint64_t>(nIdx) * C * outH * outW
170	            + static_cast<uint64_t>(cIdx) * outH * outW
171	            + static_cast<uint64_t>(hOut) * outW
172	            + static_cast<uint32_t>(wStart)], yOutLocal_, static_cast<uint32_t>(curW));
173	        yOutQueue_.FreeTensor(yOutLocal_);
174	    }
175	
176	    __aicore__ inline void ComputeTile(int curW, int wStart) {
177	        // DeQue input row
178	        AscendC::LocalTensor<T> xInDeq = xInQueue_.DeQue<T>();
179	
180	        // Cast input to FP32
181	        AscendC::LocalTensor<float> xFp32;
182	        CastInputToFp32(xFp32, xInDeq, xCastBuf_, W);
183	
184	        // Allocate output tile
185	        yOutLocal_ = yOutQueue_.AllocTensor<T>();
186	
187	        // Compute element-by-element using scalar index computation
188	        // (unavoidable for nearest-neighbor mapping)
189	        for (int wOff = 0; wOff < curW; ++wOff) {
190	            int wOut = wStart + wOff;
191	            int wIn = ComputeNearestIdx(wOut, W, outW, alignCorners);
192	
193	            // Read from UB row at position wIn
194	            float val = xFp32.GetValue(wIn);
195	
196	            // Prepare output for FP32 write
197	            if constexpr (std::is_same_v<T, float>) {
198	                yFp32Local_ = yOutLocal_.template ReinterpretCast<float>();
199	            } else {
200	                yFp32Local_ = yCastBuf_.Get<float>();
201	            }
202	            yFp32Local_.SetValue(wOff, val);
203	        }
204	
205	        // Cast output back if needed
206	        if constexpr (!std::is_same_v<T, float>) {
207	            AscendC::Cast(yOutLocal_, yFp32Local_, AscendC::RoundMode::CAST_NONE, curW);
208	            AscendC::PipeBarrier<PIPE_V>();
209	        }
210	
211	        // EnQue output
212	        yOutQueue_.EnQue(yOutLocal_);
213	
214	        // Free input
215	        xInQueue_.FreeTensor(xInDeq);
216	    }
217	
218	    __aicore__ inline int32_t ComputeNearestIdx(
219	        int32_t idxOut, int32_t inSize, int32_t outSize, int32_t alignCorners)
220	    {
221	        float coord;
222	        if (alignCorners) {
223	            // coord = idxOut * (inSize - 1) / max(outSize - 1, 1)
224	            float scaleNum = static_cast<float>(inSize - 1);
225	            int32_t denom = (outSize > 1) ? (outSize - 1) : 1;
226	            float scaleDen = static_cast<float>(denom);
227	            coord = static_cast<float>(idxOut) * scaleNum / scaleDen;
228	            // round: floor(coord + 0.5f)
229	            coord = coord + 0.5f;
230	        } else {
231	            // coord = idxOut * inSize / outSize (floor)
232	            coord = static_cast<float>(idxOut) *
233	                static_cast<float>(inSize) / static_cast<float>(outSize);
234	        }
235	
236	        int32_t result = static_cast<int32_t>(coord);
237	        // Clamp to [0, inSize - 1]
238	        if (result < 0) { result = 0; }
239	        if (result >= inSize) { result = inSize - 1; }
240	        return result;
241	    }
242	
243	    __aicore__ inline void InitAivBuffers() {
244	        // One input row (size W) and one output tile (size tileW)
245	        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, tileW * sizeof(T));
246	        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, tileW * sizeof(T));
247	
248	        if constexpr (!std::is_same_v<T, float>) {
249	            // Cast buffer for input row (fp32)
250	            pipe_.InitBuffer(xCastBuf_, tileW * sizeof(float));
251	            // Cast buffer for output tile (fp32)
252	            pipe_.InitBuffer(yCastBuf_, tileW * sizeof(float));
253	        }
254	    }
255	
256	private:
257	    // Problem dimensions
258	    int32_t N, C, H, W;
259	    int32_t outH, outW;
260	    int32_t alignCorners;
261	
262	    // Tiling
263	    int32_t ncBlock, ncNum, usedCoreNum, tasksPerCore;
264	    int32_t tileW, wTileCount;
265	
266	    // GM tensors
267	    AscendC::GlobalTensor<T> xGM_;
268	    AscendC::GlobalTensor<T> yGM_;
269	
270	    // Pipe
271	    AscendC::TPipe pipe_;
272	
273	    // Queues
274	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
275	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
276	
277	    // Cast buffers (only for fp16/bf16)
278	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
279	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
280	
281	    // Locals
282	    AscendC::LocalTensor<T> xInLocal_;
283	    AscendC::LocalTensor<T> yOutLocal_;
284	    AscendC::LocalTensor<float> yFp32Local_;
285	};
286	
