288	// Kernel entry point
289	// =========================================================================
290	
291	extern "C" __global__ __aicore__ void interpolate_nearest(
292	    GM_ADDR x, GM_ADDR y,
293	    int32_t N, int32_t C, int32_t H, int32_t W,
294	    int32_t outH, int32_t outW,
295	    int32_t alignCorners,
296	    int32_t ncBlock, int32_t ncNum, int32_t usedCoreNum, int32_t tasksPerCore,
297	    int32_t tileW, int32_t wTileCount,
298	    int64_t dtypeFlag)
299	{
300	    if (dtypeFlag == 0) {
301	        KernelInterpolateNearest<float> kernel;
302	        kernel.Init(x, y, N, C, H, W, outH, outW, alignCorners,
303	            ncBlock, ncNum, usedCoreNum, tasksPerCore, tileW, wTileCount);
304	        kernel.Process();
305	    } else if (dtypeFlag == 1) {
306	        KernelInterpolateNearest<half> kernel;
