// Interpolate Nearest — AscendC kernel (device side)
// Input:  x[N, C, H, W]
// Output: y[N, C, outH, outW]
// Algorithm: nearest-neighbor interpolation
//
// Tiling: N*C pairs distributed across cores.
// For each output column tile, compute nearest source index per element,
// read source value from GM (using 1-element copy for non-fp32, direct for fp32),
// and write output tile to UB then GM.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b) {
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

__aicore__ inline int32_t ComputeNearestIdx(
    int32_t idxOut, int32_t inSize, int32_t outSize, int32_t alignCorners)
{
    float coord;
    if (alignCorners != 0) {
        float scaleNum = static_cast<float>(inSize - 1);
        int32_t denom = (outSize > 1) ? (outSize - 1) : 1;
        coord = static_cast<float>(idxOut) * scaleNum /
                static_cast<float>(denom) + 0.5f;
    } else {
        coord = static_cast<float>(idxOut) *
                static_cast<float>(inSize) / static_cast<float>(outSize);
    }
    int32_t result = static_cast<int32_t>(coord);
    if (result < 0) { result = 0; }
    if (result >= inSize) { result = inSize - 1; }
    return result;
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T>& src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{
        1U, count * static_cast<uint32_t>(sizeof(T)), 0U, 0U, 0U};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Kernel class
// =========================================================================

template <typename T>
class KernelInterpolateNearest {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t N, int32_t C, int32_t H, int32_t W,
        int32_t outH, int32_t outW,
        int32_t alignCorners,
        int32_t ncBlock, int32_t ncNum, int32_t usedCoreNum, int32_t tasksPerCore,
        int32_t tileW, int32_t wTileCount)
    {
        this->N = N; this->C = C; this->H = H; this->W = W;
        this->outH = outH; this->outW = outW;
        this->alignCorners = alignCorners;
        this->ncBlock = ncBlock; this->ncNum = ncNum;
        this->usedCoreNum = usedCoreNum; this->tasksPerCore = tasksPerCore;
        this->tileW = tileW; this->wTileCount = wTileCount;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x),
            static_cast<uint64_t>(N) * C * H * W);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y),
            static_cast<uint64_t>(N) * C * outH * outW);

        if ASCEND_IS_AIV {
            InitAivBuffers();
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= ncNum) { continue; }

                for (int ncOff = 0; ncOff < ncBlock; ++ncOff) {
                    int ncIdx = bx * ncBlock + ncOff;
                    if (ncIdx >= N * C) { continue; }

                    int nIdx = ncIdx / C;
                    int cIdx = ncIdx % C;

                    uint64_t xChBase = static_cast<uint64_t>(nIdx) * C * H * W +
                                       static_cast<uint64_t>(cIdx) * H * W;
                    uint64_t yChBase = static_cast<uint64_t>(nIdx) * C * outH * outW +
                                       static_cast<uint64_t>(cIdx) * outH * outW;

                    for (int hOut = 0; hOut < outH; ++hOut) {
                        int hIn = ComputeNearestIdx(hOut, H, outH, alignCorners);
                        uint64_t xRowBase = xChBase + static_cast<uint64_t>(hIn) * W;
                        uint64_t yRowBase = yChBase + static_cast<uint64_t>(hOut) * outW;

                        for (int wTileIdx = 0; wTileIdx < wTileCount; ++wTileIdx) {
                            int wStart = wTileIdx * tileW;
                            int curW = (wStart + tileW <= outW) ? tileW : (outW - wStart);
                            if (curW <= 0) { continue; }

                            ComputeTile(xRowBase, yRowBase, wStart, curW);
                            CopyOutTile(yRowBase, wStart, curW);
                        }
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void ComputeTile(uint64_t xRowBase, uint64_t yRowBase,
                                        int wStart, int curW) {
        // Allocate output tile
        yBufLocal_ = yOutQueue_.AllocTensor<T>();

        if constexpr (std::is_same_v<T, float>) {
            // FP32: direct scalar reads from GM
            AscendC::LocalTensor<float> yFp32View =
                yBufLocal_.template ReinterpretCast<float>();
            for (int wOff = 0; wOff < curW; ++wOff) {
                int wOut = wStart + wOff;
                int wIn = ComputeNearestIdx(wOut, W, outW, alignCorners);
                float srcVal = xGM_[xRowBase + static_cast<uint64_t>(wIn)].GetValue(0);
                yFp32View.SetValue(wOff, srcVal);
            }
        } else {
            // FP16/BF16: use 1-element copy + Cast to float for each element
            AscendC::LocalTensor<float> yCastView = yCastBuf_.Get<float>();
            AscendC::LocalTensor<T> srcOne = srcBuf_.Get<T>();
            AscendC::LocalTensor<float> srcFloat = srcFloatBuf_.Get<float>();

            for (int wOff = 0; wOff < curW; ++wOff) {
                int wOut = wStart + wOff;
                int wIn = ComputeNearestIdx(wOut, W, outW, alignCorners);

                // Copy 1 element from GM to UB
                AscendC::DataCopyExtParams cp{
                    1U, static_cast<uint32_t>(sizeof(T)), 0U, 0U, 0U};
                AscendC::DataCopyPadExtParams<T> pp{true, 0U, 0U, static_cast<T>(0)};
                AscendC::DataCopyPad(srcOne,
                    xGM_[xRowBase + static_cast<uint64_t>(wIn)], cp, pp);

                // Cast to float
                AscendC::Cast(srcFloat, srcOne, AscendC::RoundMode::CAST_NONE, 1);
                AscendC::PipeBarrier<PIPE_V>();

                // Read and write
                yCastView.SetValue(wOff, srcFloat.GetValue(0));
            }
        }

        // EnQue output for CopyOut
        yOutQueue_.EnQue(yBufLocal_);
    }

    __aicore__ inline void CopyOutTile(uint64_t yRowBase, int wStart, int curW) {
        AscendC::LocalTensor<T> yOutDeq = yOutQueue_.DeQue<T>();
        StoreUbToGm(yGM_[yRowBase + static_cast<uint64_t>(wStart)],
                    yOutDeq, static_cast<uint32_t>(curW));
        yOutQueue_.FreeTensor(yOutDeq);
    }

    __aicore__ inline void InitAivBuffers() {
        // Output tile buffer
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, tileW * sizeof(T));
        // Per-element src/cast buffers for fp16/bf16
        if constexpr (!std::is_same_v<T, float>) {
            pipe_.InitBuffer(srcBuf_, 1 * sizeof(T));
            pipe_.InitBuffer(srcFloatBuf_, 1 * sizeof(float));
            pipe_.InitBuffer(yCastBuf_, tileW * sizeof(float));
        }
    }

private:
    int32_t N, C, H, W;
    int32_t outH, outW;
    int32_t alignCorners;
    int32_t ncBlock, ncNum, usedCoreNum, tasksPerCore;
    int32_t tileW, wTileCount;

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;

    AscendC::TPipe pipe_;

    // Output queue
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // Buffers (for fp16/bf16 only)
    AscendC::TBuf<AscendC::TPosition::VECCALC> srcBuf_;        // 1 element src
    AscendC::TBuf<AscendC::TPosition::VECCALC> srcFloatBuf_;   // 1 element float
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;      // tile float buffer

    // Locals
    AscendC::LocalTensor<T> yBufLocal_;
};

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void interpolate_nearest(
    GM_ADDR x, GM_ADDR y,
    int32_t N, int32_t C, int32_t H, int32_t W,
    int32_t outH, int32_t outW,
    int32_t alignCorners,
    int32_t ncBlock, int32_t ncNum, int32_t usedCoreNum, int32_t tasksPerCore,
    int32_t tileW, int32_t wTileCount,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        KernelInterpolateNearest<float> kernel;
        kernel.Init(x, y, N, C, H, W, outH, outW, alignCorners,
            ncBlock, ncNum, usedCoreNum, tasksPerCore, tileW, wTileCount);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        KernelInterpolateNearest<half> kernel;
        kernel.Init(x, y, N, C, H, W, outH, outW, alignCorners,
            ncBlock, ncNum, usedCoreNum, tasksPerCore, tileW, wTileCount);
        kernel.Process();
    } else {
        KernelInterpolateNearest<bfloat16_t> kernel;
        kernel.Init(x, y, N, C, H, W, outH, outW, alignCorners,
            ncBlock, ncNum, usedCoreNum, tasksPerCore, tileW, wTileCount);
        kernel.Process();
    }
}
