                for (int ncOff = 0; ncOff < ncBlock; ++ncOff) {
                    int ncIdx = bx * ncBlock + ncOff;
                    if (ncIdx >= N * C) { continue; }

                    int nIdx = ncIdx / C;
                    int cIdx = ncIdx % C;

                    uint64_t xChBase = static_cast<uint64_t>(nIdx) * C * H * W +
                                       static_cast<uint64_t>(cIdx) * H * W;
                    uint64_t yChBase = static_cast<uint64_t>(nIdx) * C * outH * outW +
                                       static_cast<uint64_t>(cIdx) * outH * outW;

                    for (int hOut = 0; hOut < outH; ++hOut) {
                        ProcessOutputRow(xChBase, yChBase, hOut);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessOutputRow(uint64_t xChBase,
                                             uint64_t yChBase,
                                             int hOut) {
        int hIn = ComputeNearestIdx(hOut, H, outH, alignCorners);
        uint64_t xRowBase = xChBase + static_cast<uint64_t>(hIn) * W;
        uint64_t yRowBase = yChBase + static_cast<uint64_t>(hOut) * outW;

        // Load source row into UB (as fp32)
        LoadSrcRow(xRowBase);

        // Process output in column tiles
        int wTileCount = (outW + tileW - 1) / tileW;
        for (int wTileIdx = 0; wTileIdx < wTileCount; ++wTileIdx) {
            int wStart = wTileIdx * tileW;
            int curW = (wStart + tileW <= outW) ? tileW : (outW - wStart);
            if (curW <= 0) { continue; }
            ComputeAndWriteTile(yRowBase, wStart, curW);
        }
    }

    __aicore__ inline void LoadSrcRow(uint64_t xRowBase) {
        // Load T-typed source row from GM to UB (queue)
        xInLocal_ = xInQueue_.AllocTensor<T>();
        AscendC::DataCopyExtParams cp{
            1U, static_cast<uint32_t>(W) * static_cast<uint32_t>(sizeof(T)),
            0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<T> pp{true, 0U, 0U, static_cast<T>(0)};
        AscendC::DataCopyPad(xInLocal_, xGM_[xRowBase], cp, pp);
        xInQueue_.EnQue(xInLocal_);

        // DeQue and cast to fp32
        AscendC::LocalTensor<T> xInDeq = xInQueue_.DeQue<T>();
        if constexpr (std::is_same_v<T, float>) {
            srcFp32_ = xInDeq.template ReinterpretCast<float>();
        } else {
            srcFp32_ = xCastBuf_.Get<float>();
            AscendC::Cast(srcFp32_, xInDeq,
                          AscendC::RoundMode::CAST_NONE, W);
            AscendC::PipeBarrier<PIPE_V>();
        }
        // Keep xInDeq allocated until done with row
        srcRowDeq_ = xInDeq;
    }

    __aicore__ inline void FreeSrcRow() {
        xInQueue_.FreeTensor(srcRowDeq_);
    }

    __aicore__ inline void ComputeAndWriteTile(uint64_t yRowBase,
                                                int wStart, int curW) {
        // Allocate output tile
        yOutLocal_ = yOutQueue_.AllocTensor<T>();

        // Get fp32 view of output tile
        AscendC::LocalTensor<float> yFp32View;
        if constexpr (std::is_same_v<T, float>) {
            yFp32View = yOutLocal_.template ReinterpretCast<float>();
        } else {
            yFp32View = yCastBuf2_.Get<float>();
        }

        // Compute per-element: read from srcFp32_ (UB row) at position wIn
        for (int wOff = 0; wOff < curW; ++wOff) {
            int wOut = wStart + wOff;
            int wIn = ComputeNearestIdx(wOut, W, outW, alignCorners);
            yFp32View.SetValue(wOff, srcFp32_.GetValue(wIn));
        }

        // Cast back to T if needed
        if constexpr (!std::is_same_v<T, float>) {
            AscendC::Cast(yOutLocal_, yFp32View,
                          AscendC::RoundMode::CAST_NONE, curW);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // EnQue for CopyOut
        yOutQueue_.EnQue(yOutLocal_);

        // DeQue and write to GM
        AscendC::LocalTensor<T> yOutDeq = yOutQueue_.DeQue<T>();
        AscendC::DataCopyExtParams outCp{
            1U, static_cast<uint32_t>(curW) * static_cast<uint32_t>(sizeof(T)),
            0U, 0U, 0U};
        AscendC::DataCopyPad(yGM_[yRowBase + static_cast<uint64_t>(wStart)],
                             yOutDeq, outCp);
        yOutQueue_.FreeTensor(yOutDeq);
    }

    __aicore__ inline void InitAivBuffers() {
        // Source row buffer (size W elements)
        int32_t srcRowSize = W * static_cast<int32_t>(sizeof(T));
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, srcRowSize);

        // Output tile buffer (size tileW elements)
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM,
                         tileW * static_cast<int32_t>(sizeof(T)));

        if constexpr (!std::is_same_v<T, float>) {
            // Cast buffer for source row (fp32)
            pipe_.InitBuffer(xCastBuf_, W * static_cast<int32_t>(sizeof(float)));
            // Cast buffer for output tile (fp32)
            pipe_.InitBuffer(yCastBuf2_,
                             tileW * static_cast<int32_t>(sizeof(float)));
        }
    }

private:
    int32_t N, C, H, W;
    int32_t outH, outW;
    int32_t alignCorners;
    int32_t ncBlock, ncNum, usedCoreNum, tasksPerCore;
    int32_t tileW;

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;

    AscendC::TPipe pipe_;

    // Source row queue
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    // Output tile queue
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // Cast buffers for fp16/bf16
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;   // src row fp32
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf2_;  // output tile fp32

    // Locals
    AscendC::LocalTensor<T> xInLocal_;
    AscendC::LocalTensor<T> srcRowDeq_;
    AscendC::LocalTensor<float> srcFp32_;
    AscendC::LocalTensor<T> yOutLocal_;
};

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void interpolate_nearest(
    GM_ADDR x, GM_ADDR y,
    int32_t N, int32_t C, int32_t H, int32_t W,
    int32_t outH, int32_t outW,
    int32_t alignCorners,
    int32_t ncBlock, int32_t ncNum, int32_t usedCoreNum, int32_t tasksPerCore,
    int32_t tileW, int32_t wTileCount,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        KernelInterpolateNearest<float> kernel;
        kernel.Init(x, y, N, C, H, W, outH, outW, alignCorners,
            ncBlock, ncNum, usedCoreNum, tasksPerCore, tileW, wTileCount);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        KernelInterpolateNearest<half> kernel;
        kernel.Init(x, y, N, C, H, W, outH, outW, alignCorners,
            ncBlock, ncNum, usedCoreNum, tasksPerCore, tileW, wTileCount);
        kernel.Process();
    } else {
        KernelInterpolateNearest<bfloat16_t> kernel;
        kernel.Init(x, y, N, C, H, W, outH, outW, alignCorners,
            ncBlock, ncNum, usedCoreNum, tasksPerCore, tileW, wTileCount);
        kernel.Process();
    }
}
