// Shared kernel for Interpolate (Nearest + Bilinear, all dtypes)

#pragma once

#include "kernel_operator.h"

constexpr int32_t INTERP_BUFFER_NUM = 2;

// ---- helpers ----

__aicore__ inline int32_t NearestIdx(
    int32_t idxOut, int32_t inSize, int32_t outSize, int32_t alignCorners)
{
    float coord;
    if (alignCorners != 0) {
        float scale = static_cast<float>(inSize - 1);
        int32_t denom = (outSize > 1) ? (outSize - 1) : 1;
        coord = static_cast<float>(idxOut) * scale /
                static_cast<float>(denom) + 0.5f;
    } else {
        coord = static_cast<float>(idxOut) *
                static_cast<float>(inSize) / static_cast<float>(outSize);
    }
    int32_t r = static_cast<int32_t>(coord);
    if (r < 0) r = 0;
    if (r >= inSize) r = inSize - 1;
    return r;
}

// Returns source coordinate (as float), not rounded
__aicore__ inline float BilinearSrcCoord(
    int32_t idxOut, int32_t inSize, int32_t outSize, int32_t alignCorners)
{
    if (alignCorners != 0) {
        float s = static_cast<float>(inSize - 1);
        float d = static_cast<float>(outSize > 1 ? outSize - 1 : 1);
        return static_cast<float>(idxOut) * s / d;
    }
    // align_corners=False: src = (idxOut + 0.5) * inSize/outSize - 0.5
    return (static_cast<float>(idxOut) + 0.5f) *
           static_cast<float>(inSize) /
           static_cast<float>(outSize) - 0.5f;
}

__aicore__ inline int32_t FloorClampIdx(float coord, int32_t inSize) {
    int32_t r = static_cast<int32_t>(coord);
    if (r < 0) r = 0;
    if (r >= inSize) r = inSize - 1;
    return r;
}

template <typename T>
class KernelInterpolate {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t N, int32_t C, int32_t H, int32_t W,
        int32_t outH, int32_t outW,
        int32_t mode,        // 0=nearest, 1=bilinear
        int32_t alignCorners,
        int32_t ncBlock, int32_t ncNum, int32_t usedCoreNum, int32_t tasksPerCore,
        int32_t tileW, int32_t wTileCount)
    {
        this->N = N; this->C = C; this->H = H; this->W = W;
        this->outH = outH; this->outW = outW;
        this->mode = mode; this->alignCorners = alignCorners;
        this->ncBlock = ncBlock; this->ncNum = ncNum;
        this->usedCoreNum = usedCoreNum; this->tasksPerCore = tasksPerCore;
        this->tileW = tileW;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x),
            static_cast<uint64_t>(N) * C * H * W);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y),
            static_cast<uint64_t>(N) * C * outH * outW);

        if ASCEND_IS_AIV {
            if (mode == 0) {
                // Nearest: 1 src row buffer
                pipe_.InitBuffer(xRowQ_, INTERP_BUFFER_NUM,
                                 W * static_cast<int32_t>(sizeof(T)));
            } else {
                // Bilinear: 2 src row buffers
                pipe_.InitBuffer(xRow0Q_, INTERP_BUFFER_NUM,
                                 W * static_cast<int32_t>(sizeof(T)));
                pipe_.InitBuffer(xRow1Q_, INTERP_BUFFER_NUM,
                                 W * static_cast<int32_t>(sizeof(T)));
                if constexpr (!std::is_same_v<T, float>) {
                    pipe_.InitBuffer(xr0Cast_, W * static_cast<int32_t>(sizeof(float)));
                    pipe_.InitBuffer(xr1Cast_, W * static_cast<int32_t>(sizeof(float)));
                }
            }
            pipe_.InitBuffer(yOutQueue_, INTERP_BUFFER_NUM,
                             tileW * static_cast<int32_t>(sizeof(T)));
            if constexpr (!std::is_same_v<T, float>) {
                pipe_.InitBuffer(yTileCast_, tileW * static_cast<int32_t>(sizeof(float)));
            }
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= ncNum) continue;
                for (int ncOff = 0; ncOff < ncBlock; ++ncOff) {
                    int ncIdx = bx * ncBlock + ncOff;
                    if (ncIdx >= N * C) continue;
                    int nIdx = ncIdx / C, cIdx = ncIdx % C;
                    uint64_t xChBase = static_cast<uint64_t>(nIdx) * C * H * W +
                                       static_cast<uint64_t>(cIdx) * H * W;
                    uint64_t yChBase = static_cast<uint64_t>(nIdx) * C * outH * outW +
                                       static_cast<uint64_t>(cIdx) * outH * outW;
                    for (int hOut = 0; hOut < outH; ++hOut) {
                        if (mode == 0) {
                            ProcessNearestRow(xChBase, yChBase, hOut);
                        } else {
                            ProcessBilinearRow(xChBase, yChBase, hOut);
                        }
                    }
                }
            }
        }
    }

private:
    // ---- Nearest ----
    __aicore__ inline void ProcessNearestRow(uint64_t xChBase, uint64_t yChBase, int hOut) {
        int hIn = NearestIdx(hOut, H, outH, alignCorners);
        uint64_t xRowBase = xChBase + static_cast<uint64_t>(hIn) * W;
        uint64_t yRowBase = yChBase + static_cast<uint64_t>(hOut) * outW;

        AscendC::LocalTensor<T> srcRow = xRowQ_.AllocTensor<T>();
        {
            AscendC::DataCopyExtParams cp{
                1U, static_cast<uint32_t>(W) * static_cast<uint32_t>(sizeof(T)),
                0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<T> pp{true, 0U, 0U, static_cast<T>(0)};
            AscendC::DataCopyPad(srcRow, xGM_[xRowBase], cp, pp);
        }
        xRowQ_.EnQue(srcRow);
        AscendC::LocalTensor<T> srcDeq = xRowQ_.DeQue<T>();

        int localWtCount = (outW + tileW - 1) / tileW;
        for (int wt = 0; wt < localWtCount; ++wt) {
            int wStart = wt * tileW, curW = (wStart + tileW <= outW) ? tileW : (outW - wStart);
            if (curW <= 0) continue;
            AscendC::LocalTensor<T> yTile = yOutQueue_.AllocTensor<T>();
            for (int wo = 0; wo < curW; ++wo) {
                int wIn = NearestIdx(wStart + wo, W, outW, alignCorners);
                yTile.SetValue(wo, srcDeq.GetValue(wIn));
            }
            yOutQueue_.EnQue(yTile);
            AscendC::LocalTensor<T> yOutDeq = yOutQueue_.DeQue<T>();
            AscendC::DataCopyExtParams outCp{
                1U, static_cast<uint32_t>(curW) * static_cast<uint32_t>(sizeof(T)),
                0U, 0U, 0U};
            AscendC::DataCopyPad(yGM_[yRowBase + static_cast<uint64_t>(wStart)],
                                 yOutDeq, outCp);
            yOutQueue_.FreeTensor(yOutDeq);
        }
        xRowQ_.FreeTensor(srcDeq);
    }

    // ---- Bilinear ----
    __aicore__ inline void ProcessBilinearRow(uint64_t xChBase, uint64_t yChBase, int hOut) {
        float hSrc = BilinearSrcCoord(hOut, H, outH, alignCorners);
        int h0 = FloorClampIdx(hSrc, H);
        int h1 = (h0 + 1 < H) ? (h0 + 1) : h0;
        float hFrac = hSrc - static_cast<float>(h0);
        if (hFrac < 0.0f) hFrac = 0.0f;
        if (hFrac > 1.0f) hFrac = 1.0f;

        uint64_t xRow0Base = xChBase + static_cast<uint64_t>(h0) * W;
        uint64_t xRow1Base = xChBase + static_cast<uint64_t>(h1) * W;
        uint64_t yRowBase = yChBase + static_cast<uint64_t>(hOut) * outW;

        // Load source rows
        AscendC::LocalTensor<T> r0 = xRow0Q_.AllocTensor<T>();
        AscendC::LocalTensor<T> r1 = xRow1Q_.AllocTensor<T>();
        {
            AscendC::DataCopyExtParams cp{
                1U, static_cast<uint32_t>(W) * static_cast<uint32_t>(sizeof(T)),
                0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<T> pp{true, 0U, 0U, static_cast<T>(0)};
            AscendC::DataCopyPad(r0, xGM_[xRow0Base], cp, pp);
            AscendC::DataCopyPad(r1, xGM_[xRow1Base], cp, pp);
        }
        xRow0Q_.EnQue(r0);
        xRow1Q_.EnQue(r1);
        AscendC::LocalTensor<T> r0Deq = xRow0Q_.DeQue<T>();
        AscendC::LocalTensor<T> r1Deq = xRow1Q_.DeQue<T>();

        // Get FP32 views
        AscendC::LocalTensor<float> r0Fp32, r1Fp32;
        if constexpr (std::is_same_v<T, float>) {
            r0Fp32 = r0Deq.template ReinterpretCast<float>();
            r1Fp32 = r1Deq.template ReinterpretCast<float>();
        } else {
            r0Fp32 = xr0Cast_.Get<float>();
            r1Fp32 = xr1Cast_.Get<float>();
            AscendC::Cast(r0Fp32, r0Deq, AscendC::RoundMode::CAST_NONE, W);
            AscendC::Cast(r1Fp32, r1Deq, AscendC::RoundMode::CAST_NONE, W);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::PipeBarrier<PIPE_ALL>();
        }

        float oneMinusHfrac = 1.0f - hFrac;

        int localWtCount = (outW + tileW - 1) / tileW;
        for (int wt = 0; wt < localWtCount; ++wt) {
            int wStart = wt * tileW, curW = (wStart + tileW <= outW) ? tileW : (outW - wStart);
            if (curW <= 0) continue;

            AscendC::LocalTensor<T> yTile = yOutQueue_.AllocTensor<T>();
            AscendC::LocalTensor<float> yFp32;
            if constexpr (std::is_same_v<T, float>) {
                yFp32 = yTile.template ReinterpretCast<float>();
            } else {
                yFp32 = yTileCast_.Get<float>();
            }

            for (int wo = 0; wo < curW; ++wo) {
                int wOut = wStart + wo;
                float wSrc = BilinearSrcCoord(wOut, W, outW, alignCorners);
                int w0 = FloorClampIdx(wSrc, W);
                int w1 = (w0 + 1 < W) ? (w0 + 1) : w0;
                float wFrac = wSrc - static_cast<float>(w0);
                if (wFrac < 0.0f) wFrac = 0.0f;
                if (wFrac > 1.0f) wFrac = 1.0f;
                float oneMinusWfrac = 1.0f - wFrac;

                float v00 = r0Fp32.GetValue(w0);
                float v01 = r0Fp32.GetValue(w1);
                float v10 = r1Fp32.GetValue(w0);
                float v11 = r1Fp32.GetValue(w1);

                float top = oneMinusWfrac * v00 + wFrac * v01;
                float bot = oneMinusWfrac * v10 + wFrac * v11;
                float val = oneMinusHfrac * top + hFrac * bot;

                yFp32.SetValue(wo, val);
            }

            if constexpr (!std::is_same_v<T, float>) {
                AscendC::Cast(yTile, yFp32, AscendC::RoundMode::CAST_NONE, curW);
                AscendC::PipeBarrier<PIPE_V>();
            }

            yOutQueue_.EnQue(yTile);
            AscendC::LocalTensor<T> yOutDeq = yOutQueue_.DeQue<T>();
            AscendC::DataCopyExtParams outCp{
                1U, static_cast<uint32_t>(curW) * static_cast<uint32_t>(sizeof(T)),
                0U, 0U, 0U};
            AscendC::DataCopyPad(yGM_[yRowBase + static_cast<uint64_t>(wStart)],
                                 yOutDeq, outCp);
            yOutQueue_.FreeTensor(yOutDeq);
        }

        xRow0Q_.FreeTensor(r0Deq);
        xRow1Q_.FreeTensor(r1Deq);
    }

private:
    int32_t N, C, H, W, outH, outW;
    int32_t mode, alignCorners;  // 0=nearest, 1=bilinear
    int32_t ncBlock, ncNum, usedCoreNum, tasksPerCore, tileW;

    AscendC::GlobalTensor<T> xGM_, yGM_;
    AscendC::TPipe pipe_;

    // nearest buffers
    AscendC::TQue<AscendC::TPosition::VECIN, INTERP_BUFFER_NUM> xRowQ_;
    // bilinear buffers
    AscendC::TQue<AscendC::TPosition::VECIN, INTERP_BUFFER_NUM> xRow0Q_;
    AscendC::TQue<AscendC::TPosition::VECIN, INTERP_BUFFER_NUM> xRow1Q_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xr0Cast_, xr1Cast_;
    // shared output
    AscendC::TQue<AscendC::TPosition::VECOUT, INTERP_BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yTileCast_;
};
