// Shared kernel for Interpolate (Nearest + Bilinear)
#pragma once
#include "kernel_operator.h"

constexpr int32_t INTERP_BUF_NUM = 2;

__aicore__ inline int32_t NearestIdx(
    int32_t idxOut, int32_t inSize, int32_t outSize, int32_t alignCorners)
{
    float coord;
    if (alignCorners != 0) {
        float s = static_cast<float>(inSize - 1);
        int32_t denom = (outSize > 1) ? (outSize - 1) : 1;
        coord = static_cast<float>(idxOut) * s / static_cast<float>(denom) + 0.5f;
    } else {
        coord = static_cast<float>(idxOut) * static_cast<float>(inSize) /
                static_cast<float>(outSize);
    }
    int32_t r = static_cast<int32_t>(coord);
    if (r < 0) r = 0;
    if (r >= inSize) r = inSize - 1;
    return r;
}

__aicore__ inline float BilinearSrcCoord(
    int32_t idxOut, int32_t inSize, int32_t outSize, int32_t alignCorners)
{
    if (alignCorners != 0) {
        float s = static_cast<float>(inSize - 1);
        float d = static_cast<float>(outSize > 1 ? outSize - 1 : 1);
        return static_cast<float>(idxOut) * s / d;
    }
    return (static_cast<float>(idxOut) + 0.5f) *
           static_cast<float>(inSize) / static_cast<float>(outSize) - 0.5f;
}

__aicore__ inline int32_t FloorClampIdx(float coord, int32_t inSize) {
    int32_t r = static_cast<int32_t>(coord);
    if (r < 0) r = 0;
    if (r >= inSize) r = inSize - 1;
    return r;
}

template <typename T>
class KernelInterpolate {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t N, int32_t C, int32_t H, int32_t W,
        int32_t outH, int32_t outW,
        int32_t mode, int32_t alignCorners,
        int32_t ncBlock, int32_t ncNum, int32_t usedCoreNum, int32_t tasksPerCore,
        int32_t tileW, int32_t wTileCount)
    {
        this->N = N; this->C = C; this->H = H; this->W = W;
        this->outH = outH; this->outW = outW;
        this->mode = mode; this->alignCorners = alignCorners;
        this->ncBlock = ncBlock; this->ncNum = ncNum;
        this->usedCoreNum = usedCoreNum; this->tasksPerCore = tasksPerCore;
        this->tileW = tileW;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x),
            static_cast<uint64_t>(N) * C * H * W);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y),
            static_cast<uint64_t>(N) * C * outH * outW);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int i = 0; i < tasksPerCore; ++i) {
                int bx = coreIdx * tasksPerCore + i;
                if (bx >= ncNum) continue;
                for (int j = 0; j < ncBlock; ++j) {
                    int ncIdx = bx * ncBlock + j;
                    if (ncIdx >= N * C) continue;
                    int nIdx = ncIdx / C, cIdx = ncIdx % C;
                    uint64_t xCh = static_cast<uint64_t>(nIdx) * C * H * W +
                                   static_cast<uint64_t>(cIdx) * H * W;
                    uint64_t yCh = static_cast<uint64_t>(nIdx) * C * outH * outW +
                                   static_cast<uint64_t>(cIdx) * outH * outW;
                    for (int hOut = 0; hOut < outH; ++hOut) {
                        if (mode == 0) ProcessNearestRow(xCh, yCh, hOut);
                        else ProcessBilinearRow(xCh, yCh, hOut);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void InitAivBuffers() {
        if (mode == 0) {
            pipe_.InitBuffer(xRowQ_, INTERP_BUF_NUM, W * static_cast<int32_t>(sizeof(T)));
        } else {
            pipe_.InitBuffer(xRow0Q_, INTERP_BUF_NUM, W * static_cast<int32_t>(sizeof(T)));
            pipe_.InitBuffer(xRow1Q_, INTERP_BUF_NUM, W * static_cast<int32_t>(sizeof(T)));
            if constexpr (std::is_same_v<T, half>) {
                pipe_.InitBuffer(xr0Cast_, W * static_cast<int32_t>(sizeof(float)));
                pipe_.InitBuffer(xr1Cast_, W * static_cast<int32_t>(sizeof(float)));
            }
        }
        pipe_.InitBuffer(yOutQueue_, INTERP_BUF_NUM, tileW * static_cast<int32_t>(sizeof(T)));
        if constexpr (std::is_same_v<T, half>) {
            pipe_.InitBuffer(yTileCast_, tileW * static_cast<int32_t>(sizeof(float)));
        }
    }

    // ---- Nearest ----
    __aicore__ inline void ProcessNearestRow(uint64_t xCh, uint64_t yCh, int hOut) {
        int hIn = NearestIdx(hOut, H, outH, alignCorners);
        uint64_t xRow = xCh + static_cast<uint64_t>(hIn) * W;
        uint64_t yRow = yCh + static_cast<uint64_t>(hOut) * outW;

        AscendC::LocalTensor<T> srcRow = xRowQ_.AllocTensor<T>();
        {
            AscendC::DataCopyExtParams cp{
                1U, static_cast<uint32_t>(W) * static_cast<uint32_t>(sizeof(T)),
                0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<T> pp{true, 0U, 0U, static_cast<T>(0)};
            AscendC::DataCopyPad(srcRow, xGM_[xRow], cp, pp);
        }
        xRowQ_.EnQue(srcRow);
        AscendC::LocalTensor<T> srcDeq = xRowQ_.DeQue<T>();

        int localWtCount = (outW + tileW - 1) / tileW;
        for (int wt = 0; wt < localWtCount; ++wt) {
            int wStart = wt * tileW, curW = (wStart + tileW <= outW) ? tileW : (outW - wStart);
            if (curW <= 0) continue;
            AscendC::LocalTensor<T> yTile = yOutQueue_.AllocTensor<T>();
            for (int wo = 0; wo < curW; ++wo) {
                int wIn = NearestIdx(wStart + wo, W, outW, alignCorners);
                yTile.SetValue(wo, srcDeq.GetValue(wIn));
            }
            yOutQueue_.EnQue(yTile);
            AscendC::LocalTensor<T> yOutDeq = yOutQueue_.DeQue<T>();
            AscendC::DataCopyExtParams outCp{
                1U, static_cast<uint32_t>(curW) * static_cast<uint32_t>(sizeof(T)),
                0U, 0U, 0U};
            AscendC::DataCopyPad(yGM_[yRow + static_cast<uint64_t>(wStart)], yOutDeq, outCp);
            yOutQueue_.FreeTensor(yOutDeq);
        }
        xRowQ_.FreeTensor(srcDeq);
    }

    // ---- Bilinear (fp32/fp16 only; bf16 uses host-side conversion to fp32) ----
    __aicore__ inline void ProcessBilinearRow(uint64_t xCh, uint64_t yCh, int hOut) {
        float hSrc = BilinearSrcCoord(hOut, H, outH, alignCorners);
        int h0 = FloorClampIdx(hSrc, H);
        int h1 = (h0 + 1 < H) ? (h0 + 1) : h0;
        float hFrac = hSrc - static_cast<float>(h0);
        if (hFrac < 0.0f) hFrac = 0.0f; else if (hFrac > 1.0f) hFrac = 1.0f;

        uint64_t xR0 = xCh + static_cast<uint64_t>(h0) * W;
        uint64_t xR1 = xCh + static_cast<uint64_t>(h1) * W;
        uint64_t yRow = yCh + static_cast<uint64_t>(hOut) * outW;

        AscendC::LocalTensor<T> r0 = xRow0Q_.AllocTensor<T>();
        AscendC::LocalTensor<T> r1 = xRow1Q_.AllocTensor<T>();
        {
            AscendC::DataCopyExtParams cp{
                1U, static_cast<uint32_t>(W) * static_cast<uint32_t>(sizeof(T)),
                0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<T> pp{true, 0U, 0U, static_cast<T>(0)};
            AscendC::DataCopyPad(r0, xGM_[xR0], cp, pp);
            AscendC::DataCopyPad(r1, xGM_[xR1], cp, pp);
        }
        xRow0Q_.EnQue(r0); xRow1Q_.EnQue(r1);
        AscendC::LocalTensor<T> r0Deq = xRow0Q_.DeQue<T>();
        AscendC::LocalTensor<T> r1Deq = xRow1Q_.DeQue<T>();

        AscendC::LocalTensor<float> r0Fp32, r1Fp32;
        if constexpr (std::is_same_v<T, half>) {
            r0Fp32 = xr0Cast_.Get<float>();
            r1Fp32 = xr1Cast_.Get<float>();
            AscendC::Cast(r0Fp32, r0Deq, AscendC::RoundMode::CAST_NONE, W);
            AscendC::Cast(r1Fp32, r1Deq, AscendC::RoundMode::CAST_NONE, W);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::PipeBarrier<PIPE_ALL>();
        } else {
            // float: direct reinterpret
            r0Fp32 = r0Deq.template ReinterpretCast<float>();
            r1Fp32 = r1Deq.template ReinterpretCast<float>();
        }

        float oh = 1.0f - hFrac;
        int localWtCount = (outW + tileW - 1) / tileW;
        for (int wt = 0; wt < localWtCount; ++wt) {
            int wStart = wt * tileW, cw = (wStart + tileW <= outW) ? tileW : (outW - wStart);
            if (cw <= 0) continue;

            AscendC::LocalTensor<T> yTile = yOutQueue_.AllocTensor<T>();
            AscendC::LocalTensor<float> yFp;
            if constexpr (std::is_same_v<T, half>) {
                yFp = yTileCast_.Get<float>();
            } else {
                yFp = yTile.template ReinterpretCast<float>();
            }

            for (int wo = 0; wo < cw; ++wo) {
                int wOut = wStart + wo;
                float wSrc = BilinearSrcCoord(wOut, W, outW, alignCorners);
                int w0 = FloorClampIdx(wSrc, W);
                int w1 = (w0 + 1 < W) ? (w0 + 1) : w0;
                float wFrac = wSrc - static_cast<float>(w0);
                if (wFrac < 0.0f) wFrac = 0.0f; else if (wFrac > 1.0f) wFrac = 1.0f;
                float ow = 1.0f - wFrac;

                float v00 = r0Fp32.GetValue(w0), v01 = r0Fp32.GetValue(w1);
                float v10 = r1Fp32.GetValue(w0), v11 = r1Fp32.GetValue(w1);
                yFp.SetValue(wo, oh * (ow * v00 + wFrac * v01) +
                                   hFrac * (ow * v10 + wFrac * v11));
            }

            if constexpr (std::is_same_v<T, half>) {
                AscendC::Cast(yTile, yFp, AscendC::RoundMode::CAST_NONE, cw);
                AscendC::PipeBarrier<PIPE_V>();
            }
            yOutQueue_.EnQue(yTile);

            AscendC::LocalTensor<T> yOutDeq = yOutQueue_.DeQue<T>();
            AscendC::DataCopyExtParams oc{
